#include "all_your_base.h"

#include <cassert>
#include <limits>
#include <stdexcept>
#include <vector>

static bool throws_invalid(unsigned int input_base,
                           std::vector<unsigned int> input_digits,
                           unsigned int output_base) {
    try {
        all_your_base::convert(input_base, input_digits, output_base);
    } catch (const std::invalid_argument &) {
        return true;
    } catch (...) {
        return false;
    }
    return false;
}

int main() {
    assert((all_your_base::convert(2, {1,0,0,0,0}, 16) == std::vector<unsigned int>{1,0}));
    assert((all_your_base::convert(16, {15,15}, 2) == std::vector<unsigned int>{1,1,1,1,1,1,1,1}));
    assert((all_your_base::convert(10, {0,0,42}, 10) == std::vector<unsigned int>{4,2}));
    assert((all_your_base::convert(7, {0,0,0}, 2) == std::vector<unsigned int>{}));
    assert((all_your_base::convert(3, {1,1,2,0}, 3) == std::vector<unsigned int>{1,1,2,0}));

    const unsigned int max_base = std::numeric_limits<unsigned int>::max();
    assert((all_your_base::convert(max_base, {max_base - 1}, max_base) == std::vector<unsigned int>{max_base - 1}));
    assert((all_your_base::convert(max_base, {max_base - 1}, max_base - 1) == std::vector<unsigned int>{1,0}));

    assert(throws_invalid(1, {1}, 10));
    assert(throws_invalid(10, {1}, 1));
    assert(throws_invalid(8, {0,8,1}, 10));
}
